/** Persistent, repeatable OFFLINE checks; call explicitly, never runs on import.
 * Tests use real source rows with known amounts; no network/credentials required.
 * Mock HTTP tests validate plumbing only, not language/model quality.
 */
export async function selfTest() {
  const results: { name: string; passed: boolean; error?: string }[] = [];
  const assert = (v: unknown, message = 'Assertion failed') => { if (!v) throw new Error(message); };
  const eq = (a: unknown, b: unknown) => assert(JSON.stringify(a) === JSON.stringify(b), `${JSON.stringify(a)} != ${JSON.stringify(b)}`);
  const test = async (name: string, fn: () => unknown | Promise<unknown>) => {
    try { await fn(); results.push({ name, passed: true }); }
    catch (e) { results.push({ name, passed: false, error: e instanceof Error ? e.message : String(e) }); }
  };
  const rejects = (fn: () => unknown) => { let caught = false; try { fn(); } catch { caught = true; } assert(caught, 'Expected rejection'); };
  const fixture = (): Input & { plan: Plan } => ({ description: 'Remove 100 SF of acoustical ceiling tile only in the kitchen. Small-volume work.',
    plan: { summary: 'Tile demolition', items: [{ id: 'demo', category: 'Demolition', description: 'Remove acoustical ceiling tile only', location: 'kitchen ceiling', certainty: 'stated',
      evidence: 'Remove 100 SF of acoustical ceiling tile only', quantity: { method: 'direct', basis: 'stated',
        measurements: [{ value: 100, unit: 'SF', evidence: '100 SF' }], explanation: 'Explicit measured ceiling area' },
      catalogId: sourceId(3), matchReason: 'Tile only, small volume explicitly specified; confirm on site' }],
      questions: [], assumptions: [], exclusions: ['Grid removal'], reviewItems: [], conflicts: [] } });
  const first = (x: Input & { plan: Plan }) => x.plan.items[0];
  await test('catalog row count and source hash', () => { eq(RAW_CATALOG.length, 12107); eq(SOURCE_AUDIT.sha256.length, 64); });
  await test('known source row preserved', () => eq(catalogRow(sourceId(3))?.slice(2, 8), ['', 0.67, 0.77, 0.018, 0.1, 'SF']));
  await test('100 SF at 0.77 = 77; no double counting', () => { const out = pricePlan(fixture()); eq(out.catalogSubtotal, 77); eq(out.projectTotal, null); eq(out.currency, null); });
  await test('source metadata matches physical row', () => { const out = pricePlan(fixture()); eq(out.lines[0].source?.row, 3); eq(out.lines[0].source?.raw, catalogRow(sourceId(3))); });
  await test('unknown ID cannot price', () => { const x = fixture(); first(x).catalogId = 'invented'; eq(pricePlan(x).catalogSubtotal, null); });
  await test('out-of-range row cannot price', () => eq(catalogRow(sourceId(99999)), null));
  await test('negative adjustment rows quarantined', () => { for (const row of [3649, 3650, 9353, 9354]) assert(rowIssues(catalogRow(sourceId(row))!).length); });
  await test('all source totals reconcile', () => { for (const r of RAW_CATALOG) assert(Math.abs((r[4] as number) - [r[2], r[3], r[6]].reduce<number>((a, b) => a + (numeric(b) ? b : 0), 0)) <= 0.025); });
  await test('exact duplicate count matches audit', () => eq(RAW_CATALOG.length - new Set(RAW_CATALOG.map(r => JSON.stringify(r))).size, 18));
  await test('search returns real positive unique rows', () => { const rows = searchCatalog('remove acoustical tile small volume', 'SF', 20); assert(rows.length > 0); eq(new Set(rows.map(r => JSON.stringify(catalogRow(r.id)))).size, rows.length); assert(rows.every(r => !rowIssues(catalogRow(r.id)!).length)); });
  await test('unknown search stays empty', () => eq(searchCatalog('xylophonicxyzzy'), []));
  await test('search bounded', () => rejects(() => searchCatalog('tile', undefined, 1000)));
  await test('square yards to square feet', () => eq(convertQuantity(10, 'SY', 'SF'), 90));
  await test('cubic feet to cubic yards', () => eq(convertQuantity(54, 'CF', 'CY'), 2));
  await test('metric area conversion', () => assert(Math.abs(convertQuantity(1, 'm2', 'SF')! - 10.7639104) < 0.000001));
  await test('linear and area incompatible', () => eq(convertQuantity(10, 'LF', 'SF'), null));
  await test('ambiguous roofing square not silently converted', () => eq(convertQuantity(1, 'Sq', 'SF'), null));
  await test('CSF is not guessed', () => eq(convertQuantity(100, 'SF', 'CSF'), null));
  await test('pair alias correct, each not pair', () => { eq(convertQuantity(3, 'Pr', 'Pair'), 3); eq(convertQuantity(3, 'Ea', 'Pair'), null); });
  await test('unit mismatch withheld', () => { const x = fixture(); first(x).quantity.measurements[0].unit = 'LF'; eq(pricePlan(x).catalogSubtotal, null); });
  await test('rectangle area uses dimensions', () => { const x = fixture(); x.description += ' 10 ft by 12 ft.'; first(x).quantity = { method: 'rectangle_area', basis: 'stated', measurements: [{ value: 10, unit: 'ft', evidence: '10 ft' }, { value: 12, unit: 'ft', evidence: '12 ft' }], explanation: 'Measured rectangle' }; eq(pricePlan(x).catalogSubtotal, 92.4); });
  await test('rectangle perimeter formula', () => { const x = fixture(); x.description = '10 ft by 12 ft'; const i = first(x); i.quantity = { method: 'rectangle_perimeter', basis: 'stated', measurements: [{ value: 10, unit: 'ft', evidence: '10 ft' }, { value: 12, unit: 'ft', evidence: '12 ft' }], explanation: 'Perimeter' }; eq(takeoff(i, x.description)?.value, 44); });
  await test('slab volume converts inch thickness', () => { const x = fixture(); x.description = '10 ft by 12 ft by 4 inches'; const i = first(x); i.quantity = { method: 'box_volume', basis: 'stated', measurements: [{ value: 10, unit: 'ft', evidence: '10 ft' }, { value: 12, unit: 'ft', evidence: '12 ft' }, { value: 4, unit: 'inches', evidence: '4 inches' }], explanation: 'Slab dimensions' }; eq(takeoff(i, x.description)?.value, 40); });
  await test('assumed quantity stays unpriced', () => { const x = fixture(); first(x).quantity.basis = 'assumed'; eq(pricePlan(x).catalogSubtotal, null); });
  await test('numeric fabrication rejected', () => { const x = fixture(); first(x).quantity.measurements[0].value = 200; eq(pricePlan(x).catalogSubtotal, null); });
  await test('fabricated evidence rejected', () => { const x = fixture(); first(x).quantity.measurements[0].evidence = '200 SF'; eq(pricePlan(x).catalogSubtotal, null); });
  await test('conditional scope withheld', () => { const x = fixture(); first(x).certainty = 'conditional'; eq(pricePlan(x).catalogSubtotal, null); });
  await test('inferred scope withheld', () => { const x = fixture(); first(x).certainty = 'inferred'; eq(pricePlan(x).catalogSubtotal, null); });
  await test('conflicting dimensions block all pricing', () => { const x = fixture(); x.plan.conflicts = ['100 SF conflicts with stated 200 SF']; eq(pricePlan(x).catalogSubtotal, null); });
  await test('duplicate scope id rejected', () => { const x = fixture(); x.plan.items.push(structuredClone(first(x))); rejects(() => pricePlan(x)); });
  await test('duplicate scope extent blocks both lines', () => { const x = fixture(); x.plan.items.push({ ...structuredClone(first(x)), id: 'demo2' }); eq(pricePlan(x).pricedLineCount, 0); });
  await test('different locations retain separate line items', () => { const x = fixture(); x.plan.items.push({ ...structuredClone(first(x)), id: 'demo2', location: 'bedroom' }); eq(pricePlan(x).catalogSubtotal, 154); });
  await test('missing item not silently zero or complete', () => { const x = fixture(); x.plan.items.push({ ...structuredClone(first(x)), id: 'unsupported', location: 'other', catalogId: null }); const y = pricePlan(x); eq(y.catalogSubtotal, 77); eq(y.unpricedLineCount, 1); eq(y.projectTotal, null); eq(y.questions.length, 0); });
  await test('empty scope has no zero budget', () => { const x = fixture(); x.plan.items = []; eq(pricePlan(x).catalogSubtotal, null); });
  await test('edits recalculate, never trust amount input', () => { const x = fixture(); x.description = x.description.replace('100', '200'); first(x).evidence = first(x).evidence.replace('100', '200'); first(x).quantity.measurements[0] = { value: 200, unit: 'SF', evidence: '200 SF' }; eq(pricePlan(x).catalogSubtotal, 154); rejects(() => pricePlan({ ...x, amount: 1 } as Input)); });
  await test('NaN rejected', () => { const x = fixture(); first(x).quantity.measurements[0].value = NaN; rejects(() => pricePlan(x)); });
  await test('zero quantity rejected', () => { const x = fixture(); first(x).quantity.measurements[0].value = 0; rejects(() => pricePlan(x)); });
  await test('negative quantity rejected', () => { const x = fixture(); first(x).quantity.measurements[0].value = -1; rejects(() => pricePlan(x)); });
  await test('excess scope bounded', () => { const x = fixture(); x.plan.items = Array.from({ length: 41 }, () => structuredClone(first(x))); rejects(() => pricePlan(x)); });
  await test('prototype keys rejected', () => rejects(() => validate(JSON.parse('{"description":"test","__proto__":{}}'), INPUT_SCHEMA)));
  await test('markup and gross margin differ', () => { eq(sellingPrice(100, 'markup', 0.2), 120); eq(sellingPrice(100, 'gross_margin', 0.2), 125); rejects(() => sellingPrice(100, 'gross_margin', 1)); });
  const post = (body: unknown, headers: Record<string, string> = {}) => new Request('https://isolated.invalid/estimate', { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: JSON.stringify(body) });
  const allowed = { authorize: async () => 'offline-test-user', allowRequest: async () => true };
  await test('default HTTP handler disconnected', async () => eq((await createHandler()(post(fixture()))).status, 503));
  await test('no authorization means no planner call', async () => { let called = false; const h = createHandler({ ...allowed, authorize: async () => null, planner: async () => { called = true; return fixture().plan; } }); eq((await h(post({ description: 'test' }))).status, 401); eq(called, false); });
  await test('quota rejection happens before planning', async () => eq((await createHandler({ ...allowed, allowRequest: async () => false })(post(fixture()))).status, 429));
  await test('natural-language without provider fails explicitly', async () => eq((await createHandler(allowed)(post({ description: 'Repair kitchen' }))).status, 503));
  await test('edited plan HTTP arithmetic', async () => { const r = await createHandler(allowed)(post(fixture())); eq(r.status, 200); eq((await r.json()).catalogSubtotal, 77); });
  await test('mock planner pipeline', async () => { const r = await createHandler({ ...allowed, planner: async () => fixture().plan })(post({ description: fixture().description })); eq(r.status, 200); eq((await r.json()).catalogSubtotal, 77); });
  await test('bad planner shape rejected', async () => eq((await createHandler({ ...allowed, planner: async () => ({ bogus: true }) as unknown as Plan })(post({ description: 'test' }))).status, 502));
  await test('disallowed browser origin rejected', async () => eq((await createHandler(allowed)(post(fixture(), { origin: 'https://evil.invalid' }))).status, 403));
  await test('explicit CORS origin returned', async () => { const r = await createHandler({ ...allowed, allowedOrigins: ['https://good.invalid'] })(post(fixture(), { origin: 'https://good.invalid' })); eq(r.headers.get('access-control-allow-origin'), 'https://good.invalid'); });
  await test('OPTIONS preflight', async () => eq((await createHandler({ allowedOrigins: ['https://good.invalid'] })(new Request('https://isolated.invalid', { method: 'OPTIONS', headers: { origin: 'https://good.invalid' } }))).status, 204));
  await test('GET rejected', async () => eq((await createHandler()(new Request('https://isolated.invalid'))).status, 405));
  await test('wrong media type rejected', async () => eq((await createHandler(allowed)(post(fixture(), { 'content-type': 'text/plain' }))).status, 415));
  await test('malformed JSON rejected', async () => eq((await createHandler(allowed)(new Request('https://isolated.invalid', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{' }))).status, 400));
  await test('oversized body rejected', async () => eq((await createHandler(allowed)(post({ description: 'x'.repeat(100000) }))).status, 413));
  await test('description length bounded', async () => eq((await createHandler(allowed)(post({ description: 'x'.repeat(12001) }))).status, 400));
  await test('no internal credential leakage on adapter failure', async () => { const r = await createHandler({ ...allowed, authorize: async () => { throw new Error('secret-value'); } })(post(fixture())); eq(r.status, 500); assert(!(await r.text()).includes('secret-value')); });
  await test('cancelled requests bounded', async () => { const c = new AbortController(); c.abort(); const r = await createHandler(allowed)(new Request('https://isolated.invalid', { method: 'POST', signal: c.signal, body: '{}' })); eq(r.status, 504); });
  await test('provider requires explicit settings', () => rejects(() => createOpenAIPlanner({ enabled: true, apiKey: '', model: '' })));
  const modelEnvelope = (value: unknown) => new Response(JSON.stringify({ status: 'completed', output: [{ type: 'message', content: [{ type: 'output_text', text: JSON.stringify(value) }] }] }));
  const runMockProvider = async (second: (data: { items: { id: string; candidates: { id: string }[] }[] }) => unknown) => {
    let calls = 0;
    const planner = createOpenAIPlanner({ enabled: true, apiKey: 'offline-test-placeholder', model: 'offline-test-model',
      transport: async (url, init) => {
        eq(url, 'https://api.openai.com/v1/responses');
        const body = JSON.parse(init!.body as string);
        eq(body.store, false); eq(body.text.format.strict, true);
        calls++;
        return modelEnvelope(calls === 1 ? fixture().plan : second(JSON.parse(body.input[0].content[0].text)));
      } });
    return { plan: await planner(fixture().description, new AbortController().signal), calls };
  };
  const rejectedAsync = async (fn: () => Promise<unknown>, status: number) => {
    let caught = false;
    try { await fn(); } catch (e) { caught = true; assert(e instanceof EstimateError); eq((e as EstimateError).status, status); }
    assert(caught, 'Expected asynchronous rejection');
  };
  await test('two-stage provider contract with mocked transport', async () => {
    const r = await runMockProvider(data => ({ matches: data.items.map(i => ({ id: i.id, catalogId: i.candidates[0].id, reason: 'Mock selection only' })) }));
    eq(r.calls, 2); assert(catalogRow(r.plan.items[0].catalogId!));
  });
  await test('AI hallucinated source ID rejected', async () => rejectedAsync(() => runMockProvider(data => ({ matches: data.items.map(i => ({ id: i.id, catalogId: 'invented-id', reason: 'fabricated' })) })), 502));
  await test('AI known but noncandidate source ID rejected', async () => rejectedAsync(() => runMockProvider(data => ({ matches: data.items.map(i => ({ id: i.id, catalogId: sourceId(12108), reason: 'outside retrieved set' })) })), 502));
  await test('AI incomplete match list rejected', async () => rejectedAsync(() => runMockProvider(() => ({ matches: [] })), 502));
  await test('AI null match preserved as unresolved', async () => { const r = await runMockProvider(data => ({ matches: data.items.map(i => ({ id: i.id, catalogId: null, reason: 'No compatible specification' })) })); eq(r.plan.items[0].catalogId, null); });
  await test('AI duplicate match IDs rejected', async () => rejectedAsync(() => runMockProvider(data => ({ matches: [0, 1].map(() => ({ id: data.items[0].id, catalogId: null, reason: 'duplicate' })) })), 502));
  for (const [name, payload, status] of [
    ['refusal', { status: 'completed', output: [{ content: [{ type: 'refusal', refusal: 'Cannot comply' }] }] }, 422],
    ['incomplete generation', { status: 'incomplete', output: [] }, 502],
    ['schema-invalid output', { status: 'completed', output: [{ content: [{ type: 'output_text', text: '{"bogus":true}' }] }] }, 502]
  ] as const) {
    await test(`AI ${name} handled safely`, async () => {
      const planner = createOpenAIPlanner({ enabled: true, apiKey: 'offline-placeholder', model: 'offline-model', transport: async () => new Response(JSON.stringify(payload)) });
      await rejectedAsync(() => planner(fixture().description, new AbortController().signal), status);
    });
  }
  await test('AI upstream failure mapped without secret text', async () => {
    const planner = createOpenAIPlanner({ enabled: true, apiKey: 'offline-placeholder', model: 'offline-model', transport: async () => new Response('private provider details', { status: 429 }) });
    await rejectedAsync(() => planner(fixture().description, new AbortController().signal), 502);
  });
  return { suite: 'offline deterministic and HTTP checks', passed: results.filter(x => x.passed).length,
    failed: results.filter(x => !x.passed).length, results,
    unexecuted: ['Live model/provider evaluation', 'Contractor-reviewed corpus scoring', 'Deno/Supabase runtime and load testing'] };
}

